pages.css:
.sow-body{font-family:'Poppins','Segoe UI',Arial,sans-serif;display:flex;flex-direction:column;gap:8px;padding:6px 4px 2px;box-sizing:border-box;height:100%;}
.sow-label{font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:#E2571C;}
.sow-title{font-family:'Times New Roman',Times,serif;font-size:22px;font-weight:800;color:#1a1a2e;border-bottom:3px solid #F5A623;padding-bottom:6px;margin:0;}
.sow-note{font-size:11.5px;color:#6c757d;line-height:1.4;background:#fff8f3;border:1.5px dashed #E2571C;border-radius:8px;padding:7px 10px;}
.sow-table{width:100%;border-collapse:collapse;font-size:11.5px;margin-top:2px;}
.sow-table th{background:#E2571C;color:#fff;text-align:left;padding:5px 7px;font-weight:700;font-size:11px;}
.sow-table td{padding:4px 7px;border-bottom:1px solid #f0c9a8;vertical-align:top;line-height:1.3;}
.sow-table tr:nth-child(even) td{background:#fffaf0;}
.sow-table .c{text-align:center;white-space:nowrap;font-weight:700;color:#E2571C;}
.sow-table .tile{font-family:Georgia,serif;font-weight:600;font-size:11px;}
.sow-table .note{color:#6c757d;font-size:10.5px;}
.sow-tp{font-family:'Times New Roman',Times,serif;text-align:center;display:flex;flex-direction:column;justify-content:center;align-items:center;height:100%;width:100%;box-sizing:border-box;padding:24px 40px;}
.sow-tp-line{width:90px;height:3px;background:#F5A623;margin:12px auto;border-radius:2px;}
.sow-tp-title{font-size:30px;font-weight:800;color:#1a1a2e;letter-spacing:1px;}
.sow-tp-sub{font-size:16px;color:#E2571C;font-style:italic;margin-top:6px;}
.sow-tp-ed{font-size:12px;font-weight:800;color:#c45a12;text-transform:uppercase;letter-spacing:1.4px;margin-top:14px;font-family:'Poppins',sans-serif;}
.sow-tp-note{margin-top:20px;font-size:12px;color:#6c757d;font-style:italic;line-height:1.55;font-family:'Poppins',sans-serif;max-width:480px;}
.sow-toc{padding:10px 8px;}
.sow-toc-title{font-size:22px;font-weight:800;color:#1a1a2e;border-bottom:3px solid #F5A623;padding-bottom:8px;margin-bottom:12px;font-family:'Times New Roman',serif;}
.sow-toc-row{display:flex;justify-content:space-between;padding:7px 4px;border-bottom:1px solid #f0c9a8;font-size:13px;}
.sow-toc-row span:last-child{font-weight:800;color:#E2571C;min-width:48px;text-align:right;}

.sow-sw{margin-top:6px;padding:8px 10px;background:#fff8f3;border:1.5px solid #f0c9a8;border-radius:8px;}
.sow-sw-label{font-size:11px;font-weight:800;color:#E2571C;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;}
.sow-sw-chips{display:flex;flex-wrap:wrap;gap:4px;}
.sow-sw-chip{display:inline-block;padding:3px 8px;background:#E2571C;color:#fff;border-radius:6px;font-size:11px;font-weight:600;}
.sow-sw-count{font-size:10.5px;color:#6c757d;margin-top:4px;}

